package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.util.function.ThrowingSupplier;

/** F1 preparation and F2 live admission are served only to the independently pinned
 * supervisor mTLS identity. Worker/model credentials cannot select this private role. */
public final class FormalEvaluationSupervisorGate {
 private final JdbcTemplate db;private final FormalEvaluationControlAccess controls;private final FormalEvaluationDeployments deployments;
 private final FormalEvaluationContextReads contexts;private final PermissionSchema json;private final TaskSourceVerifierSchema parser=new TaskSourceVerifierSchema();
 public FormalEvaluationSupervisorGate(DataSource data,FormalEvaluationControlAccess controls,FormalEvaluationDeployments deployments,FormalEvaluationContextReads contexts,PermissionSchema json){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.controls=controls;this.deployments=deployments;this.contexts=contexts;this.json=json;}
 public JsonNode read(HttpServletRequest http,JsonNode request,boolean admission)throws Exception{
  ProfessionalRuntimeObservations.closed(request,admission?Set.of("binding","session_id","isolation_receipt_id","supervision_sha256","process_unit_sha256","supervisor_instance_id"):Set.of("binding","session_id"));var b=request.required("binding");ProfessionalRuntimeObservations.jsonBinding(b);String tenant=text(b,"tenant_id"),run=text(b,"run_id"),step=text(b,"step_id"),session=text(request,"session_id");WireValues.uuid(session);var nodeKind=one(db.query("SELECT node_kind FROM formal_evaluation_node WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2",(r,n)->r.getString(1),tenant,run,step));var deployment=deployments.require(nodeKind);
  return controls.withSupervisorReads(http,tenant,run,deployment,reads->ThrowingSupplier.of(()->reads.execute(a->ThrowingSupplier.of(()->{
   reads.requireSupervisor();var j=reads.job();if(!db.queryForList("SELECT receipt_id FROM formal_evaluation_cancel_intent WHERE tenant_id=? AND run_id=? LIMIT 1",tenant,run).isEmpty())deny();var node=one(j.nodes().stream().filter(n->n.stepId().equals(step)).toList());same(node.node().nodeKind(),text(deployment.value(),"node_kind"));same(json.tree(node.node().role()),deployment.value().required("role_version"));
   var lease=one(db.queryForList("SELECT * FROM run_step WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND status='RUNNING' AND lease_expires_at>UTC_TIMESTAMP(6) FOR UPDATE",tenant,j.projectId(),run,step));same(text(deployment.value(),"worker_service_uri"),lease.get("lease_owner"));same(b.required("lease_generation").longValue(),((Number)lease.get("lease_generation")).longValue());same(text(b,"input_sha256"),lease.get("input_sha256"));
   var row=one(db.queryForList("SELECT * FROM formal_evaluation_runtime_prepare WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND action_id=? AND lease_generation=? AND session_id=? AND created_by=? LIMIT 2",tenant,j.projectId(),run,step,text(b,"action_id"),b.required("lease_generation").longValue(),session,j.actorId()));
   var envelope=parser.read((String)row.get("envelope_json"));var launch=parser.read((String)row.get("launch_json"));same(parser.hash(envelope),row.get("envelope_sha256"));same(parser.hash(launch),row.get("launch_sha256"));same(text(b,"step_envelope_sha256"),row.get("envelope_sha256"));same(deployment.sha256(),row.get("deployment_sha256"));same(json.manifestSha256(),row.get("schema_manifest_sha256"));same(b,launch.required("binding"));same(session,text(launch,"session_id"));same("EVALUATION_VERIFICATION",text(launch,"purpose"));same("SYSTEM_JOB",text(envelope,"execution_kind"));same("EVALUATION_VERIFICATION",text(envelope,"job_type"));same(node.node().nodeKind(),text(launch,"node_kind"));
   contexts.requirePins(a,run,step,envelope.required("context_reads"));same(text(envelope,"input_sha256"),text(launch,"prompt_sha256"));same(text(envelope,"input_sha256"),WireValues.sha256(text(launch,"prompt").getBytes(java.nio.charset.StandardCharsets.UTF_8)));
   var receipt=json.object().put("session_id",session).put("envelope_sha256",parser.hash(envelope)).put("launch_sha256",parser.hash(launch));same(receipt,parser.read((String)one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND action='evaluation.runtime.prepared' AND result='SUCCESS' AND request_id=? AND trace_id=? LIMIT 2",(r,n)->r.getString(1),tenant,j.projectId(),row.get("audit_id"),j.actorId(),session,run))));same(receipt,parser.read((String)one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND event_type='evaluation.runtime.prepared' LIMIT 2",(r,n)->r.getString(1),tenant,row.get("event_id"),session))));
   var expires=one(db.query("SELECT LEAST(lease_expires_at,TIMESTAMPADD(SECOND,?,UTC_TIMESTAMP(6))) FROM run_step WHERE tenant_id=? AND run_id=? AND step_id=?",(r,n)->r.getTimestamp(1).toInstant(),deployment.value().required("supervisor_gate_lifetime_seconds").intValue(),tenant,run,step));var out=json.object().put("session_id",session).put("expires_at",expires.toString());out.set("binding",b.deepCopy());
   if(admission){var start=parser.read((String)one(db.query("SELECT canonical_start FROM professional_runtime_session WHERE tenant_id=? AND run_id=? AND step_id=? AND session_id=? AND admission_state='OPEN' AND action_id=? AND lease_generation=? LIMIT 2",(r,n)->r.getString(1),tenant,run,step,session,text(b,"action_id"),b.required("lease_generation").longValue())));same(b,start.required("binding"));same(text(request,"isolation_receipt_id"),text(start,"isolation_receipt_id"));same(text(request,"supervision_sha256"),text(start,"supervision_sha256"));var supervised=one(db.queryForList("SELECT * FROM professional_runtime_supervision WHERE tenant_id=? AND session_id=? AND phase='ADMITTED' AND receipt_id=? LIMIT 2",tenant,session,text(start,"isolation_receipt_id")));var evidence=parser.read((String)supervised.get("canonical_evidence"));same(parser.hash(evidence),supervised.get("evidence_sha256"));same(text(start,"supervision_sha256"),supervised.get("evidence_sha256"));FormalEvaluationSupervisor.validateStoredAdmission(evidence);same(b,evidence.required("binding"));same(deployment.sha256(),text(evidence,"deployment_sha256"));same(text(deployment.value(),"supervisor_service_uri"),supervised.get("supervisor_service_uri"));same(text(deployment.value(),"supervisor_certificate_sha256"),supervised.get("certificate_sha256"));same(text(deployment.value(),"supervisor_trust_revision"),supervised.get("trust_revision"));same(j.actorId(),supervised.get("created_by"));same(json.manifestSha256(),supervised.get("schema_manifest_sha256"));same(evidence,parser.read((String)one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND action='evaluation.professional.admitted' AND result='SUCCESS' AND request_id=? AND trace_id=? LIMIT 2",(r,n)->r.getString(1),tenant,j.projectId(),supervised.get("audit_id"),j.actorId(),session,text(evidence,"receipt_id")))));same(evidence,parser.read((String)one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND event_type='evaluation.professional.admitted' LIMIT 2",(r,n)->r.getString(1),tenant,supervised.get("event_id"),session))));same(text(request,"supervisor_instance_id"),text(evidence,"supervisor_instance_id"));same(text(request,"process_unit_sha256"),parser.hash(evidence.required("process_unit")));out.put("process_unit_sha256",text(request,"process_unit_sha256")).put("supervisor_instance_id",text(request,"supervisor_instance_id")).put("admission","CURRENT").put("isolation_receipt_id",text(start,"isolation_receipt_id")).put("supervision_sha256",text(start,"supervision_sha256"));}
   else{out.set("prepared_launch",launch);out.put("prepared_envelope_base64",Base64.getEncoder().encodeToString(ContentReadAuthorization.canonicalBytes(envelope)));out.set("preparation_receipt",receipt);}reads.requireSupervisor();return out;
  }).get())).get());
 }
 private static String text(JsonNode n,String k){if(!n.required(k).isTextual())deny();return n.required(k).textValue();}private static <T>T one(List<T> xs){if(xs.size()!=1||xs.get(0)==null)deny();return xs.get(0);}private static void same(Object a,Object b){if(!Objects.equals(a,b))deny();}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
